export const getPostV0ApiWebhooksUrl = () => {
  return `/v0/api_webhooks`;
};

export const postV0ApiWebhooks = async (
  apiWebhookModel: ApiWebhookModel,
  options?: RequestInit
): Promise<ApiWebhookResponseModel> => {
  return fetcher<Promise<ApiWebhookResponseModel>>(getPostV0ApiWebhooksUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(apiWebhookModel),
  });
};

/**
 * @summary Retrieve rates and values for a booking cancellation
 */
export const getGetV0CancellationPoliciesUrl = (
  params?: GetV0CancellationPoliciesParams
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  return normalizedParams.size
    ? `/v0/cancellation_policies?${normalizedParams.toString()}`
    : `/v0/cancellation_policies`;
};

export const getV0CancellationPolicies = async (
  params?: GetV0CancellationPoliciesParams,
  options?: RequestInit
): Promise<CancellationPoliciesModel> => {
  return fetcher<Promise<CancellationPoliciesModel>>(
    getGetV0CancellationPoliciesUrl(params),
    {
      ...options,
      method: "GET",
    }
  );
};

