export const getPatchV0BookingsBookingIdUrl = (
  bookingId: string,
  params?: PatchV0BookingsBookingIdParams
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  return normalizedParams.size
    ? `/v0/bookings/${bookingId}?${normalizedParams.toString()}`
    : `/v0/bookings/${bookingId}`;
};

export const patchV0BookingsBookingId = async (
  bookingId: string,
  patchBookingRequestV0Model: PatchBookingRequestV0Model,
  params?: PatchV0BookingsBookingIdParams,
  options?: RequestInit
): Promise<void> => {
  return fetcher<Promise<void>>(
    getPatchV0BookingsBookingIdUrl(bookingId, params),
    {
      ...options,
      method: "PATCH",
      headers: { "Content-Type": "application/json", ...options?.headers },
      body: JSON.stringify(patchBookingRequestV0Model),
    }
  );
};

