/**
 * <div class="doc-tags flex mt-3">
<div class="text-xxs font-semibold flex items-center py-1 px-2 uppercase rounded-small bg-blue text-white uppercase last:mr-0 mr-1">
Gm Full Login
</div>
<div class="text-xxs font-semibold flex items-center py-1 px-2 uppercase rounded-small bg-blue text-white uppercase last:mr-0 mr-1">
Go Login
</div>
<div class="text-xxs font-semibold flex items-center py-1 px-2 uppercase rounded-small bg-blue text-white uppercase last:mr-0 mr-1">
Partner Login
</div>
</div>


 * @summary Get a list of saved proposals
 */
export const getGetV0ProposalsSavedUrl = (
  params?: GetV0ProposalsSavedParams
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  return normalizedParams.size
    ? `/v0/proposals/saved?${normalizedParams.toString()}`
    : `/v0/proposals/saved`;
};

export const getV0ProposalsSaved = async (
  params?: GetV0ProposalsSavedParams,
  options?: RequestInit
): Promise<SavedProposalsModel | void> => {
  return fetcher<Promise<SavedProposalsModel | void>>(
    getGetV0ProposalsSavedUrl(params),
    {
      ...options,
      method: "GET",
    }
  );
};

