/**
 * @summary Retrieve all the facilities of a specific product
 */
export const getGetV2ProductsProductIdFacilitiesUrl = (
  productId: string,
  params?: GetV2ProductsProductIdFacilitiesParams
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["filter"];

    if (value instanceof Array && explodeParameters.includes(key)) {
      value.forEach((v) =>
        normalizedParams.append(key, v === null ? "null" : v.toString())
      );
      return;
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  return normalizedParams.size
    ? `/v2/products/${productId}/facilities?${normalizedParams.toString()}`
    : `/v2/products/${productId}/facilities`;
};

