export const getGetV0CustomersCustomerIdBookingsBookingIdCrmHistoryUrl = (
  customerId: string,
  bookingId: string,
  params?: GetV0CustomersCustomerIdBookingsBookingIdCrmHistoryParams
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["filter"];

    if (value instanceof Array && explodeParameters.includes(key)) {
      value.forEach((v) =>
        normalizedParams.append(key, v === null ? "null" : v.toString())
      );
      return;
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  return normalizedParams.size
    ? `/v0/customers/${customerId}/bookings/${bookingId}/crm_history?${normalizedParams.toString()}`
    : `/v0/customers/${customerId}/bookings/${bookingId}/crm_history`;
};

