/**
 * @summary Displays wellness availabilities in a chosen village (from Booker)
 */
export const getGetV0ProductsProductIdSpasCaresCareCodeUrl = (
  productId: string,
  careCode: string,
  params?: GetV0ProductsProductIdSpasCaresCareCodeParams
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  return normalizedParams.size
    ? `/v0/products/${productId}/spas/cares/${careCode}?${normalizedParams.toString()}`
    : `/v0/products/${productId}/spas/cares/${careCode}`;
};

